package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

/** Refuses a person whose name another person on the sheet already has. */
public class CheckPersonName {
    public void check(@Val Person person, PersonRepository repository)
            throws DuplicatePersonNameException {
        if (repository.nameTaken(person.getSheetId(), person.getName(), person.getId())) {
            throw new DuplicatePersonNameException(person.getName());
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/** Gives the person one more alias: refused when any name or alias on the sheet already is it (ignoring case). */
public class AddAlias {
    public void add(@Val AliasInput input, @Val Sheet sheet, @Val Person person,
            PersonRepository repository) throws DuplicatePersonNameException {
        if (repository.nameTaken(sheet.id(), input.alias(), null)) {
            throw new DuplicatePersonNameException(input.alias());
        }
        repository.addAlias(person, input.alias());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleDuplicatePersonName {
    public void handle(@Parameter DuplicatePersonNameException ex,
            ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.CONFLICT));
    }
}
