package net.officefloor.hq.app.quick;

import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** The person on the sheet with the typed name (ignoring case), or a new one with grade A, not yet saved. */
public class FindQuickAddPerson {
    public void find(@Val QuickAdd quick, @Val Sheet sheet, PersonRepository repository,
            Out<Person> personOut, Out<QuickAddPerson> createdOut) {
        Person person = repository.findByName(sheet.id(), quick.name());
        createdOut.set(new QuickAddPerson(person == null));
        personOut.set(person != null ? person : new Person(null, sheet.id(), quick.name(), "A"));
    }
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.CheckClaimPeriod;
import net.officefloor.hq.app.period.ClosedPeriodException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.CheckClaimRetired;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.RetiredPersonException;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.hq.app.paste.PasteLine;
import net.officefloor.hq.app.paste.PasteLines;
import net.officefloor.hq.app.paste.PasteResponse;

/**
 * Adds a DRAFT claim per pasted line, in order, for the person on the sheet with that name (matched
 * as names are compared). Every line is checked first, as the claim form checks a claim (its person
 * on the sheet, its reference unused on the sheet and in the paste, its due-by outside a closed period and not after its person's retirement), so a
 * refused paste writes nothing; then each claim is saved, logged and audited as one added by the form.
 */
public class AddPastedClaims {
    public void add(@Val Sheet sheet, @Val PasteLines paste, PersonRepository people, ClaimRepository claims,
            PeriodRepository periods, RateRepository rates, SettingsRepository settings, ClaimLogRepository log,
            HolidayRepository holidays, HttpServletRequest request, Audit audit, Out<PasteResponse> result)
            throws InvalidClaimException, ClosedPeriodException, RetiredPersonException {
        Settings terms = settings.find(sheet.id());
        List<Person> persons = new ArrayList<>();
        List<Claim> built = new ArrayList<>();
        Set<String> refs = new HashSet<>();
        for (PasteLine line : paste.lines()) {
            Person person = people.findByName(sheet.id(), line.name());
            if (person == null) throw new InvalidClaimException("No one named " + line.name() + " is on the sheet");
            LocalDate date = line.claim().date() == null ? terms.entryDay(sheet.today()) : line.claim().date();
            Claim claim = new Claim(null, sheet.id(), person.getId(), line.claim().amount(), date, line.claim().note(),
                    ClaimStatus.DRAFT, null, null, null);
            claim.setRef(line.claim().ref());
            if (claim.getRef() != null && !refs.add(claim.getRef().toUpperCase(Locale.ROOT))) {
                throw new InvalidClaimException("The reference " + claim.getRef() + " is pasted more than once");
            }
            new CheckClaimRef().check(claim, claims);
            claim.fixDueBy(terms.termsFor(person, date), holidays.dates(sheet.id()));
            new CheckClaimPeriod().check(sheet, claim, periods);
            claim.setLateEntry(periods.softClosedOn(sheet.id(), claim.getDueBy()) != null);
            new CheckClaimRetired().check(sheet, claim, people);
            persons.add(person);
            built.add(claim);
        }
        String user = Audit.user(request);
        for (int i = 0; i < built.size(); i++) {
            Claim claim = built.get(i);
            claims.save(claim);
            log.record(claim, user, sheet.today(), LogClaimStatus.due(sheet, claim, people, rates, settings));
            new AuditClaimAdded().audit(sheet, persons.get(i), claim, request, audit);
        }
        result.set(new PasteResponse(built.size()));
    }
}
/**
 * Transfers the person to another sheet (a steward), not retired, and only when their name, aliases
 * and contact are free there. They arrive with their grades (and from-dates), terms, contact and
 * aliases, and their claims with their status, dates, notes, tags, frozen figures, logs and comments,
 * listed in the order they were. Each claim that had a number takes the other sheet's next, in the
 * order the claims were opened (by the sheet's today then, then the order added); a correction or
 * split names the new numbers. Figures a statement bound are lost, the statement count starts at 0,
 * and references and settle batches are not carried. They leave this sheet entirely: patron links
 * either way, pool memberships, watches and holds are dropped.
 */
public class TransferPerson {
    public void transfer(@Val TransferInput input, @Val Sheet sheet, @Val Person person, PersonRepository people,
            ClaimRepository claims, SheetRepository sheets, RoleRepository roles, SettingsRepository settings,
            PeriodRepository periods, RateRepository rates, HttpServletRequest request, Out<Transfer> transferOut)
            throws StewardOnlyException, InvalidPersonException, ViewerException, SheetArchivedException {
        String user = Audit.user(request);
        if (!Role.STEWARD.equals(roles.roleOf(sheet.id(), user))) {
            throw new StewardOnlyException("Only a steward may transfer people");
        }
        if (person.isRetired()) throw new InvalidPersonException("A retired person cannot be transferred");
        Sheet to = sheets.loadOrCreate(input.toSheet());
        if (Role.VIEWER.equals(roles.roleOf(to.id(), user))) {
            throw new ViewerException("A viewer may not change the sheet transferred to");
        }
        if (to.archived()) throw new SheetArchivedException(to.id());
        if (people.nameTaken(to.id(), person.getName(), null)) {
            throw new InvalidPersonException("That name is already on the sheet transferred to");
        }
        for (String alias : person.getAliases()) {
            if (people.nameTaken(to.id(), alias, null)) {
                throw new InvalidPersonException("An alias is already on the sheet transferred to");
            }
        }
        if (person.getContact() != null && people.contactTaken(to.id(), person.getContact(), null)) {
            throw new InvalidPersonException("That contact is already on the sheet transferred to");
        }
        Settings toSettings = settings.find(to.id());
        Rollup toBefore = Rollup.of(to.id(), to.today(), people, claims, rates, toSettings);

        // Oldest listed first, so they are listed on the other sheet as they were here.
        List<Claim> moving = new ArrayList<>(claims.findByPerson(sheet.id(), person.getId()));
        Collections.reverse(moving);
        Map<Long, LocalDate> openedOn = new HashMap<>();
        List<Claim> numbered = new ArrayList<>();
        for (Claim claim : moving) {
            if (claim.getNumber() == null) continue;
            LocalDate opened = claims.openedOn(claim);
            openedOn.put(claim.getId(), opened == null ? claim.getDate() : opened);
            numbered.add(claim);
        }
        numbered.sort(Comparator.comparing((Claim c) -> openedOn.get(c.getId()))
                .thenComparing(Claim::getId));
        Map<String, String> renumbered = new HashMap<>();
        Map<Long, String> numbers = new HashMap<>();
        for (Claim claim : numbered) {
            String number = ClaimNumbers.next(to, claim, toSettings, periods, claims);
            renumbered.put(claim.getNumber(), number);
            numbers.put(claim.getId(), number);
        }
        for (Claim claim : moving) {
            claims.transfer(claim, to.id(), numbers.get(claim.getId()),
                    claim.getCorrects() == null ? null : renumbered.getOrDefault(claim.getCorrects(), claim.getCorrects()),
                    claim.getSplitFrom() == null ? null : renumbered.getOrDefault(claim.getSplitFrom(), claim.getSplitFrom()));
        }
        people.transfer(person, to.id());
        transferOut.set(new Transfer(person, to, toBefore));
    }
}
package net.officefloor.hq.app.sheet;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/**
 * The sheet's descendants: the sheets naming it as their parent, the sheets naming those, and so
 * on. Each is listed once, and never the sheet itself.
 */
public class RespondWithDescendants {
    public void respond(@Val Sheet sheet, SheetRepository repository, ObjectResponse<DescendantsResponse> response) {
        List<String> descendants = new ArrayList<>();
        Set<String> seen = new HashSet<>(Set.of(sheet.id()));
        Deque<String> pending = new ArrayDeque<>(List.of(sheet.id()));
        while (!pending.isEmpty()) {
            for (String child : repository.children(pending.removeFirst())) {
                if (seen.add(child)) {
                    descendants.add(child);
                    pending.addLast(child);
                }
            }
        }
        response.send(new DescendantsResponse(descendants));
    }
}
package net.officefloor.hq.app.sheet;

import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The sheet store. */
@Repository
public class SheetRepository {

    private final JdbcTemplate jdbc;

    public SheetRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet with this id, created empty (its today the real date) when never loaded before. */
    public Sheet loadOrCreate(String id) {
        jdbc.update("MERGE INTO sheet USING (VALUES (CAST(? AS VARCHAR(200)), CAST(? AS DATE))) s(id, today)"
                + " ON sheet.id = s.id WHEN NOT MATCHED THEN INSERT (id, today) VALUES (s.id, s.today)",
                id, Date.valueOf(LocalDate.now()));
        return find(id);
    }

    /** The sheet with this id, or null when it was never loaded. */
    public Sheet find(String id) {
        List<Sheet> found = jdbc.query("SELECT id, today, archived FROM sheet WHERE id = ?",
                (rs, n) -> new Sheet(rs.getString("id"), rs.getDate("today").toLocalDate(),
                        rs.getBoolean("archived")), id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The sheet's today: the date the sheet uses instead of the real clock. */
    public LocalDate today(String id) {
        Sheet sheet = find(id);
        return sheet == null ? LocalDate.now() : sheet.today();
    }

    public void saveToday(String id, LocalDate today) {
        jdbc.update("UPDATE sheet SET today = ? WHERE id = ?", Date.valueOf(today), id);
    }

    /** Archive the sheet: true when this call archived it, false when it already was. */
    public boolean archive(String id) {
        return jdbc.update("UPDATE sheet SET archived = TRUE, archived_on = today WHERE id = ? AND archived = FALSE", id) > 0;
    }

    /**
     * The sheet as it stood at the end of {@code day}: that date stands in for its today, and it is
     * archived only when it was archived while its today was on or before it.
     */
    public Sheet asOf(Sheet sheet, LocalDate day) {
        List<Boolean> archived = jdbc.query("SELECT archived AND (archived_on IS NULL OR archived_on <= ?) AS archived_then"
                + " FROM sheet WHERE id = ?", (rs, n) -> rs.getBoolean("archived_then"), Date.valueOf(day), sheet.id());
        return new Sheet(sheet.id(), day, !archived.isEmpty() && archived.get(0));
    }

    /** The sheet's parent sheet's id, or null when it has none (or was never loaded). */
    public String parent(String id) {
        List<String> found = jdbc.query("SELECT parent_id FROM sheet WHERE id = ?",
                (rs, n) -> rs.getString("parent_id"), id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The ids of the sheets naming this one as their parent, in id order. */
    public List<String> children(String id) {
        return jdbc.query("SELECT id FROM sheet WHERE parent_id = ? ORDER BY id", (rs, n) -> rs.getString("id"), id);
    }

    /** Names the sheet's parent sheet (null: none). */
    public void saveParent(String id, String parent) {
        jdbc.update("UPDATE sheet SET parent_id = ? WHERE id = ?", parent, id);
    }

    /** Whether the sheet has been archived; false for a sheet never loaded. */
    public boolean isArchived(String id) {
        Sheet sheet = find(id);
        return sheet != null && sheet.archived();
    }
}

